import fs from "node:fs";
import path from "node:path";
import { awsBundle } from "./bundles/aws.js";
import { azureBundle } from "./bundles/azure.js";
import { gcpBundle } from "./bundles/gcp.js";
import { ociBundle } from "./bundles/oci.js";

const GENERATED_HEADER =
  "# Generated by Drydock. Restored on reset. Edit main.tf, not this file.\n";
const SKIP_DIRS = new Set([".terraform", ".drydock", ".aws", ".azure", ".git"]);
const SKIP_FILES = new Set([".bashrc"]);
const MAX_BYTES = 1_000_000;

const BUNDLES = {
  aws: awsBundle,
  azure: azureBundle,
  gcp: gcpBundle,
  oci: ociBundle,
};

/** Domain error raised by Workspace operations without HTTP coupling. */
export class WorkspaceError extends Error {
  constructor(code, message) {
    super(message);
    this.name = "WorkspaceError";
    this.code = code;
  }
}

/** Materializes a lab's starter files, provider bundle, and runtime environment into dest. */
export function createWorkspace({ lab, dest, lock }) {
  fs.rmSync(dest, { recursive: true, force: true });
  fs.mkdirSync(dest, { recursive: true });
  fs.cpSync(lab.starterDir, dest, { recursive: true });

  const { files, env, prepare } = buildBundles(lab, dest, lock);
  for (const [relative, contents] of Object.entries(files)) {
    const target = path.join(dest, relative);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, contents);
  }

  const drydock = path.join(dest, ".drydock");
  fs.mkdirSync(drydock, { recursive: true });
  const exports = Object.entries(env)
    .map(([key, value]) => `export ${key}=${shellQuote(value)}`)
    .join("\n");
  fs.writeFileSync(path.join(drydock, "env"), `${exports}\n`);
  fs.writeFileSync(
    path.join(drydock, "docker.env"),
    Object.entries(env)
      .map(([key, value]) => `${key}=${value}`)
      .join("\n") + "\n",
  );
  fs.writeFileSync(
    path.join(dest, ".bashrc"),
    `if [ -f "$HOME/.drydock/env" ]; then
  set -a
  . "$HOME/.drydock/env"
  set +a
fi
cd "$HOME"
PS1='drydock:\\w\\$ '
`,
  );

  return { env, prepare };
}

/** Lists learner-visible directories and files inside a Workspace root. */
export function listWorkspaceFiles(root) {
  const rootReal = fs.realpathSync(root);
  return readDir(rootReal, rootReal);
}

/** Reads a text file inside a Workspace and reports whether it is generated read-only. */
export function readWorkspaceFile(root, relative) {
  const file = resolveWorkspacePath(root, relative);
  if (!fs.existsSync(file) || !fs.statSync(file).isFile()) {
    throw new WorkspaceError("NOT_FOUND", "That file is not in the workspace.");
  }
  if (fs.statSync(file).size > MAX_BYTES) {
    throw new WorkspaceError("TOO_LARGE", "That file is too large to open here.");
  }
  const text = fs.readFileSync(file, "utf8");
  if (text.includes("\0")) {
    throw new WorkspaceError("BINARY_FILE", "That file is not text.");
  }
  return {
    path: toPosix(path.relative(fs.realpathSync(root), file)),
    text,
    readOnly: text.startsWith(GENERATED_HEADER),
  };
}

/** Writes text to an editable file inside a Workspace, rejecting generated files. */
export function writeWorkspaceFile(root, relative, text) {
  if (typeof text !== "string") {
    throw new WorkspaceError("INVALID_CONTENT", "The editor did not send text.");
  }
  if (text.length > MAX_BYTES) {
    throw new WorkspaceError("TOO_LARGE", "That file is too large to save.");
  }
  if (text.includes("\0")) {
    throw new WorkspaceError("INVALID_CONTENT", "That file is not text.");
  }
  const file = resolveWorkspacePath(root, relative);
  if (fs.existsSync(file) && fs.statSync(file).isFile()) {
    const current = fs.readFileSync(file, "utf8");
    if (current.startsWith(GENERATED_HEADER)) {
      throw new WorkspaceError("READ_ONLY", "This file is restored on reset. Edit main.tf.");
    }
  }
  fs.writeFileSync(file, text);
}

/** Removes a single Workspace directory if present. */
export function removeWorkspace(dir) {
  if (!dir) return;
  fs.rmSync(dir, { recursive: true, force: true });
}

/** Removes stale Workspace subdirectories left behind from earlier runs. */
export function pruneWorkspaces(workspacesDir) {
  if (!workspacesDir || !fs.existsSync(workspacesDir)) return;
  for (const entry of fs.readdirSync(workspacesDir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      fs.rmSync(path.join(workspacesDir, entry.name), { recursive: true, force: true });
    }
  }
}

function buildBundles(lab, workspace, lock) {
  const hclBlocks = [];
  const files = {};
  const env = {
    HOME: workspace,
    TF_CLI_CONFIG_FILE: "/opt/drydock/terraform.rc",
    TF_IN_AUTOMATION: "1",
    TF_INPUT: "0",
    CHECKPOINT_DISABLE: "1",
  };
  const prepare = [];

  for (const cloud of lab.clouds) {
    const build = BUNDLES[cloud];
    if (!build) throw new Error(`No provider bundle for ${cloud}`);
    const part = build({ lab, workspace, lock });
    if (part.hcl?.trim()) hclBlocks.push(part.hcl.trim());
    Object.assign(files, part.files);
    Object.assign(env, part.env);
    prepare.push(...(part.prepare ?? []));
  }

  if (hclBlocks.length > 0) {
    files["provider.tf"] = `${GENERATED_HEADER}${hclBlocks.join("\n\n")}\n`;
  }
  return { files, env, prepare };
}

function resolveWorkspacePath(root, relative) {
  if (typeof relative !== "string" || relative.length === 0 || relative.includes("\0")) {
    throw new WorkspaceError("INVALID_PATH", "Choose a file in the workspace.");
  }
  const rootReal = fs.realpathSync(root);
  const normalized = path.normalize(relative);
  const parts = normalized.split(path.sep).filter((part) => part && part !== ".");
  if (path.isAbsolute(normalized) || parts.includes("..")) {
    throw new WorkspaceError("INVALID_PATH", "That path is outside the workspace.");
  }
  if (parts.some((part) => SKIP_DIRS.has(part)) || (parts.length === 1 && SKIP_FILES.has(parts[0]))) {
    throw new WorkspaceError("NOT_FOUND", "That file is not part of the lab workspace.");
  }
  const target = path.resolve(rootReal, ...parts);
  const parent = path.dirname(target);
  if (!fs.existsSync(parent)) {
    throw new WorkspaceError("NOT_FOUND", "That file is not in the workspace.");
  }
  const parentReal = fs.realpathSync(parent);
  const parentRel = path.relative(rootReal, parentReal);
  if (parentRel.startsWith("..") || path.isAbsolute(parentRel)) {
    throw new WorkspaceError("INVALID_PATH", "That path is outside the workspace.");
  }
  const resolved = path.join(parentReal, path.basename(target));
  if (fs.existsSync(resolved) && fs.lstatSync(resolved).isSymbolicLink()) {
    throw new WorkspaceError("INVALID_PATH", "That path is outside the workspace.");
  }
  return resolved;
}

function readDir(dir, rootReal) {
  const nodes = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory() && SKIP_DIRS.has(entry.name)) continue;
    if (entry.isFile() && dir === rootReal && SKIP_FILES.has(entry.name)) continue;
    const full = path.join(dir, entry.name);
    const rel = toPosix(path.relative(rootReal, full));
    if (entry.isDirectory()) {
      nodes.push({ name: entry.name, path: rel, type: "dir", children: readDir(full, rootReal) });
    } else if (entry.isFile()) {
      nodes.push({ name: entry.name, path: rel, type: "file" });
    }
  }
  nodes.sort((a, b) => {
    if (a.type !== b.type) return a.type === "dir" ? -1 : 1;
    return rank(a.name) - rank(b.name) || a.name.localeCompare(b.name);
  });
  return nodes;
}

function rank(name) {
  if (name === "main.tf") return 0;
  if (name.endsWith(".tf")) return 1;
  return 2;
}

function toPosix(relative) {
  return relative.split(path.sep).join("/");
}

function shellQuote(value) {
  return `'${String(value).replaceAll("'", "'\\''")}'`;
}
